// static
bool WallpaperStubDispatch::AcceptWithResponder(
    Wallpaper* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (message->header()->name) {
    case internal::kWallpaper_SetWallpaperDeprecated_Name: {

      internal::Wallpaper_SetWallpaperDeprecated_Params_Data* params =
          reinterpret_cast<
              internal::Wallpaper_SetWallpaperDeprecated_Params_Data*>(
                  message->mutable_payload());
      
      
      // Validation for Wallpaper.0
      bool success = true;
      WallpaperSettingsPtr p_wallpaper{};
      std::string p_extension_id{};
      std::string p_extension_name{};
      Wallpaper_SetWallpaperDeprecated_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadWallpaper(&p_wallpaper))
        success = false;
      if (success && !input_data_view.ReadExtensionId(&p_extension_id))
        success = false;
      if (success && !input_data_view.ReadExtensionName(&p_extension_name))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Wallpaper::Name_, 0, false);
        return false;
      }
      Wallpaper::SetWallpaperDeprecatedCallback callback =
          Wallpaper_SetWallpaperDeprecated_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->SetWallpaperDeprecated(        
        std::move(p_wallpaper), 
        std::move(p_extension_id), 
        std::move(p_extension_name), std::move(callback));
      return true;
    }
    case internal::kWallpaper_SetWallpaper_Name: {

      internal::Wallpaper_SetWallpaper_Params_Data* params =
          reinterpret_cast<
              internal::Wallpaper_SetWallpaper_Params_Data*>(
                  message->mutable_payload());
      
      
      // Validation for Wallpaper.1
      bool success = true;
      WallpaperSettingsPtr p_wallpaper{};
      std::string p_exension_id{};
      std::string p_extension_name{};
      Wallpaper_SetWallpaper_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadWallpaper(&p_wallpaper))
        success = false;
      if (success && !input_data_view.ReadExensionId(&p_exension_id))
        success = false;
      if (success && !input_data_view.ReadExtensionName(&p_extension_name))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Wallpaper::Name_, 1, false);
        return false;
      }
      Wallpaper::SetWallpaperCallback callback =
          Wallpaper_SetWallpaper_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->SetWallpaper(        
        std::move(p_wallpaper), 
        std::move(p_exension_id), 
        std::move(p_extension_name), std::move(callback));
      return true;
    }
  }
  return false;
}
