// static
bool StructTraits<::crosapi::mojom::WallpaperSettings::DataView, ::crosapi::mojom::WallpaperSettingsPtr>::Read(
    ::crosapi::mojom::WallpaperSettings::DataView input,
    ::crosapi::mojom::WallpaperSettingsPtr* output) {
  bool success = true;
  ::crosapi::mojom::WallpaperSettingsPtr result(::crosapi::mojom::WallpaperSettings::New());
  
      if (success && !input.ReadData(&result->data))
        success = false;
      if (success && !input.ReadLayout(&result->layout))
        success = false;
      if (success && !input.ReadFilename(&result->filename))
        success = false;
  *output = std::move(result);
  return success;
}

// static
bool UnionTraits<::crosapi::mojom::SetWallpaperResult::DataView, ::crosapi::mojom::SetWallpaperResultPtr>::Read(
    ::crosapi::mojom::SetWallpaperResult::DataView input,
    ::crosapi::mojom::SetWallpaperResultPtr* output) {
  using UnionType = ::crosapi::mojom::SetWallpaperResult;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kThumbnailData: {
      std::vector<uint8_t> result_thumbnail_data;
      if (!input.ReadThumbnailData(&result_thumbnail_data))
        return false;

      *output = UnionType::NewThumbnailData(
          std::move(result_thumbnail_data));
      break;
    }
    case Tag::kErrorMessage: {
      std::string result_error_message;
      if (!input.ReadErrorMessage(&result_error_message))
        return false;

      *output = UnionType::NewErrorMessage(
          std::move(result_error_message));
      break;
    }
    default:

      return false;
  }
  return true;
}

