WallpaperAsyncWaiter::WallpaperAsyncWaiter(
    Wallpaper* proxy) : proxy_(proxy) {}

WallpaperAsyncWaiter::~WallpaperAsyncWaiter() = default;

void WallpaperAsyncWaiter::SetWallpaperDeprecated(
    WallpaperSettingsPtr wallpaper, const std::string& extension_id, const std::string& extension_name, std::vector<uint8_t>* out_thumbnail_data) {
  base::RunLoop loop;
  proxy_->SetWallpaperDeprecated(std::move(wallpaper),std::move(extension_id),std::move(extension_name),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<uint8_t>* out_thumbnail_data
,
             const std::vector<uint8_t>& thumbnail_data) {*out_thumbnail_data = std::move(thumbnail_data);
            loop->Quit();
          },
          &loop,
          out_thumbnail_data));
  loop.Run();
}

std::vector<uint8_t> WallpaperAsyncWaiter::SetWallpaperDeprecated(
    WallpaperSettingsPtr wallpaper, const std::string& extension_id, const std::string& extension_name) {
  std::vector<uint8_t> async_wait_result;
  SetWallpaperDeprecated(std::move(wallpaper),std::move(extension_id),std::move(extension_name),&async_wait_result);
  return async_wait_result;
}

void WallpaperAsyncWaiter::SetWallpaper(
    WallpaperSettingsPtr wallpaper, const std::string& exension_id, const std::string& extension_name, SetWallpaperResultPtr* out_result) {
  base::RunLoop loop;
  proxy_->SetWallpaper(std::move(wallpaper),std::move(exension_id),std::move(extension_name),
      base::BindOnce(
          [](base::RunLoop* loop,
             SetWallpaperResultPtr* out_result
,
             SetWallpaperResultPtr result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

SetWallpaperResultPtr WallpaperAsyncWaiter::SetWallpaper(
    WallpaperSettingsPtr wallpaper, const std::string& exension_id, const std::string& extension_name) {
  SetWallpaperResultPtr async_wait_result;
  SetWallpaper(std::move(wallpaper),std::move(exension_id),std::move(extension_name),&async_wait_result);
  return async_wait_result;
}






